        return 0.0
    return 1.0 - math.log(math.gcd(t, x)) / den'''}
for k,v in va.items(): open(f'v_{k}.py','w').write(src.replace(old,v))
EOF
for v in one max geo; do echo $v; /scr/wurgaft/auto-psych/agent_trees/7e8e4116c4d40231/venv/bin/python resid.py v_$v.py 2>/dev/null | head -2; done

